function login() {
    var u = String(result.get('帐号') || '');
    var p = String(result.get('密码') || '');
    if (!u || !p) { java.toast('⚠️ 请先填写帐号和密码'); return; }
    java.toast('⏳ 正在获取验证码，请在弹窗中输入（验证码会话60秒内有效，请尽快输入）');
    var code = java.getVerificationCode('https://www.book630.org/code.jpg?' + Math.random());
    if (!code || String(code).trim() === '') { java.toast('⚠️ 未输入验证码'); return; }
    java.toast('登录中...');
    var body = 'user_name=' + encodeURIComponent(u) + '&user_pass=' + java.md5Encode(p) + '&user_code=' + encodeURIComponent(String(code).trim());
    var r = java.post('https://www.book630.org/qs_login_go.php', body, {
        'Content-Type': 'application/x-www-form-urlencoded',
        'X-Requested-With': 'XMLHttpRequest',
        'User-Agent': 'Mozilla/5.0 (Linux; Android 14; Pixel 8) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Mobile Safari/537.36',
        'Referer': 'https://www.book630.org/login.html',
        'Origin': 'https://www.book630.org'
    });
    var b = String(r.body() || '').replace(/\s/g, '');
    var d = b.split('|');
    if (d[0] == '1') {
        java.toast('✅ 登录成功，可以搜索了');
        upLoginData({'帐号': u});
    } else {
        java.toast('❌ 登录失败: ' + (d[1] || '未知错误（验证码错误或已超60秒? 请重试）'));
    }
}

function register() {
    var u = String(result.get('注册帐号') || '');
    var p = String(result.get('注册密码') || '');
    var m = String(result.get('手机号') || '');
    if (!u || !p || !m) { java.toast('⚠️ 请填写注册帐号/注册密码/手机号'); return; }
    if (!/^[A-Za-z0-9]{3,15}$/.test(u)) { java.toast('⚠️ 帐号需为字母加数字，3-15字内'); return; }
    java.toast('⏳ 正在获取验证码，请在弹窗中输入');
    var code = java.getVerificationCode('https://www.book630.org/code.jpg?' + Math.random());
    if (!code || String(code).trim() === '') { java.toast('⚠️ 未输入验证码'); return; }
    java.toast('注册中...');
    var pw = java.md5Encode(p);
    var body = 'name=' + encodeURIComponent(u) + '&pass=' + pw + '&pass2=' + pw + '&mobile=' + encodeURIComponent(m) + '&code=' + encodeURIComponent(String(code).trim());
    var r = java.post('https://www.book630.org/qs_register_go.php', body, {
        'Content-Type': 'application/x-www-form-urlencoded',
        'X-Requested-With': 'XMLHttpRequest',
        'User-Agent': 'Mozilla/5.0 (Linux; Android 14; Pixel 8) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Mobile Safari/537.36',
        'Referer': 'https://www.book630.org/register.html',
        'Origin': 'https://www.book630.org'
    });
    var b = String(r.body() || '').replace(/\s/g, '');
    var d = b.split('|');
    if (d[0] == '1') {
        java.toast('✅ ' + (d[1] || '注册成功') + '（已自动登录）');
        upLoginData({'帐号': u, '注册帐号': u, '注册密码': ''});
    } else {
        java.toast('❌ 注册失败: ' + (d[1] || '未知错误（验证码错误? 帐号已存在?）'));
    }
}

